// `image-to-text`: an image to text about it, such as the text it shows, generated by a vision encoder-decoder such as TrOCR, as `transformers`' image-to-text pipeline gave it before `transformers` 5.

use std::slice;

use serde::Serialize;
use singe::DataType;

use crate::{
    error::Result,
    head::{Seq2SeqInput, Seq2SeqLm},
    model,
    processing::{
        image::{Image, ImageTransforms},
        text::TextTokenizer,
    },
    source::{LoadOptions, Source},
    task::{
        Pipeline, Task,
        text::summarization::{Seq2SeqParameters, generate_from},
    },
};

#[derive(Debug)]
pub struct ImageToTextPipeline {
    model: Seq2SeqLm,
    processor: ImageTransforms,
    tokenizer: TextTokenizer,
    data_type: DataType,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct GeneratedText {
    pub generated_text: String,
}

impl Pipeline for ImageToTextPipeline {
    const TASK: Task = Task::ImageToText;

    type Input = Image;

    type Parameters = Seq2SeqParameters;

    type Output = GeneratedText;

    fn load(source: &Source, options: LoadOptions) -> Result<Self> {
        Ok(Self {
            model: model::load(source, options)?,
            processor: ImageTransforms::load(source)?,
            tokenizer: TextTokenizer::load(source.directory())?,
            data_type: options.data_type,
        })
    }

    fn run(
        &self,
        inputs: &[Self::Input],
        parameters: &Self::Parameters,
    ) -> Result<Vec<Self::Output>> {
        let device = self.model.model().state().device()?;
        inputs
            .iter()
            .map(|image| {
                let pixels =
                    self.processor
                        .preprocess(slice::from_ref(image), device, self.data_type)?;
                Ok(GeneratedText {
                    generated_text: generate_from(
                        &self.model,
                        &self.tokenizer,
                        Seq2SeqInput::Pixels(&pixels),
                        parameters.max_new_tokens,
                    )?,
                })
            })
            .collect()
    }
}
